SELECT 'gongkao', '单位统一与换算', 'kp-trv-b-unit', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "单位统一与换算"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心法则：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "1 m/s = 3.6 km/h。考场神级常数。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、题型定义与识别"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题目给的速度是 km/h，但给的时间却是“秒”或者“分钟”，或者求的距离是“米”（如过桥问题）。"}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "二、核心公式"}]}, {"type": "katexBlock", "attrs": {"content": "1 \\text{ m/s} = \\frac{1/1000 \\text{ km}}{1/3600 \\text{ h}} = 3.6 \\text{ km/h}"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "三、标准步骤"}]}, {"type": "text-diagram", "attrs": {"type": "mermaid", "content": "flowchart TD\nA[列出已知量和目标量] --> B[比对它们的单位是否处在同一量级(千米配小时, 米配秒)]\nB --> C{是否一致?}\nC -- 不一致 --> D[利用换算系数 3.6 进行转换]\nD --> E[米每秒转千米每时乘3.6, 反之除以3.6]\nC -- 一致 --> F[直接计算]"}}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "四、例题推导"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "【例题】", "marks": [{"type": "bold"}]}, {"type": "text", "text": " 汽车速度为 72 km/h，行驶了 50 秒，走了多少米？"}]}, {"type": "orderedList", "attrs": {"start": 1}, "content": [{"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "看单位：速度是 km/h，时间是秒，求的是米。必须转换。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "换算速度：72 km/h = 72 ÷ 3.6 = 20 m/s。"}]}]}, {"type": "listItem", "content": [{"type": "paragraph", "content": [{"type": "text", "text": "计算距离：S = 20 × 50 = 1000 米。"}]}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "五、易错点纠偏"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fef2f2", "borderColor": "#ef4444", "icon": "⚠️"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "死记硬背容易反向操作：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "到底乘还是除？记住常识：汽车在高速上跑 100km/h 感觉很快了，但换算成米每秒只有三十多米。数字变小了！所以从大单位(km/h) 到 小单位(m/s) 必须是【除以】3.6。"}]}]}]}$$ AS jsonb), NULL, '单位统一与换算的核心考点与实战推导。', category_node.id, CAST('["数量关系", "行程问题", "单位统一与换算"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_trv_b_unit", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
